using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes imported contacts using the list of contacts saved on the device. Imports newly added contacts and, if at least the file database is enabled, deletes recently deleted contacts.
    /// Query result depends on the result of the previous query, so only one query is possible at the same time
    /// </summary>
    public Task<TdLib.TdApi.Objects.ImportedContacts> ChangeImportedContactsAsync(ImportedContact[] contacts = default)
    {

           using var activity =  StartCallActivity("ChangeImportedContactsAsync", typeof(ChangeImportedContacts).FullName ?? "ChangeImportedContactsAsync");

           try
           {
             return client.ChangeImportedContactsAsync(contacts);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
